CustomField.formula:
/* TRUE = needs review */
IF(
    OR(
        ISBLANK(Account.PersonContact.Birthdate),
        ISBLANK(
            Application_Timeline__r.Academic_Term__r.Dec_31_Age_Cutoff_Date__c
        )
    ),

    TRUE,

    IF(
        OR(
            TEXT(Grade_Applying_To__c) = "PK",
            TEXT(Grade_Applying_To__c) = "K",
            TEXT(Grade_Applying_To__c) = "TK",
            AND(
                ISNUMBER(TEXT(Grade_Applying_To__c)),
                VALUE(BLANKVALUE(TEXT(Grade_Applying_To__c), "0")) >= 1,
                VALUE(BLANKVALUE(TEXT(Grade_Applying_To__c), "0")) <= 12
            )
        ),

        OR(
            /* Too young */
            ADDMONTHS(
                Account.PersonContact.Birthdate,
                CASE(
                    TEXT(Grade_Applying_To__c),
                    "PK", 48,
                    "K", 60,
                    "TK", 60,
                    (
                        VALUE(BLANKVALUE(TEXT(Grade_Applying_To__c), "0")) + 5
                    ) * 12
                )
            ) >
            Application_Timeline__r.Academic_Term__r.Dec_31_Age_Cutoff_Date__c,

            /* Too old */
            ADDMONTHS(
                Account.PersonContact.Birthdate,
                CASE(
                    TEXT(Grade_Applying_To__c),
                    "PK", 60,
                    "K", 72,
                    "TK", 72,
                    (
                        VALUE(BLANKVALUE(TEXT(Grade_Applying_To__c), "0")) + 7
                    ) * 12
                )
            ) <=
            Application_Timeline__r.Academic_Term__r.Dec_31_Age_Cutoff_Date__c
        ),

        /* Unsupported grade */
        FALSE
    )
)
